    "// 输入框那一行：新版 TUI 用 U+276F，旧版用 >；后面是已键入的文本或占位提示。",
    "const INPUT_LINE_PATTERN = /^[\\u276f>]\\s?(.*)$/u;",
    "const INPUT_PLACEHOLDER_PREFIX = 'Try \"';",
