    "const MAX_PROCESS_ARGUMENTS = 8192;",
    "// pod 窗口显示名里 pod 名与标题之间的分隔，由 Claude 启动指令模块的同一常量在构建本脚本时填入（open-items W28）：",
    "// mark 据此算出与 launch 相同的 tmux 窗口名（worktree pod 去掉 \"<pod 名> · \" 前缀，§13.186）。",
    "const POD_WINDOW_TITLE_SEPARATOR = __WAKEFLOW_POD_WINDOW_TITLE_SEPARATOR__;",
    "",
    "/** @param {string} directory */",
    "function listJsonNames(directory) {",
    "  let handle = null;",
    "  /** @type {string[]} */",
    "  const names = [];",
    "  try {",
    "    handle = opendirSync(directory);",
    "    for (;;) {",
    "      const entry = handle.readSync();",
    "      if (entry === null) break;",
    "      if (entry.isFile() && entry.name.endsWith(\".json\")) names.push(entry.name);",
    "    }",
    "  } catch {",
    "    return [];",
    "  } finally {",
    "    if (handle !== null) {",
    "      try {",
    "        handle.closeSync();",
    "      } catch {",
    "        // diagnostic enumeration is already closed",
    "      }",
    "    }",
    "  }",
    "  names.sort();",
    "  return names;",
    "}",
    "",
    "/**",
    " * @param {HelperConfig} config",
    " * @returns {TmuxContext}",
    " */",
    "function tmuxContext(config) {",
    "  const tmux = config.hosts?.[\"claude-code\"]?.tmux ?? {};",
    "  const socketName =",
    "    typeof tmux.socketName === \"string\" && tmux.socketName.length > 0 ? tmux.socketName : null;",
    "  const sessionName =",
    "    typeof tmux.sessionName === \"string\" && tmux.sessionName.length > 0",
    "      ? tmux.sessionName",
    "      : DEFAULT_SESSION_NAME;",
    "  return Object.freeze({ socketName, sessionName, programId: config.program.programId });",
    "}",
    "",
    "/**",
    " * @param {TmuxContext} context",
    " * @param {readonly string[]} args",
    " */",
    "function tmuxArguments(context, args) {",
    "  return [...(context.socketName === null ? [] : [\"-L\", context.socketName]), ...args];",
    "}",
    "",
    "/**",
    " * @param {TmuxContext} context",
    " * @param {readonly string[]} args",
