    "}",
    "",
    "function claudeBinary() {",
    "  for (const directory of (process.env.PATH ?? \"\").split(path.delimiter)) {",
    "    if (directory.length === 0) continue;",
    "    const candidate = path.join(directory, \"claude\");",
    "    try {",
    "      if (statSync(candidate).isFile()) return candidate;",
    "    } catch {",
    "      // not in this directory",
    "    }",
    "  }",
    "  return \"claude\";",
    "}",
    "",
    "function currentSocketName() {",
    "  const tmuxEnvironment = process.env.TMUX;",
    "  if (typeof tmuxEnvironment !== \"string\" || tmuxEnvironment.length === 0) return null;",
    "  const socketPath = tmuxEnvironment.split(\",\")[0] ?? \"\";",
    "  return socketPath.length === 0 ? null : path.basename(socketPath);",
    "}",
    "",
    "/** @param {readonly string[]} argv */",
    "// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: moved verbatim from the inline script (1.3.0 batch 1, no behavior change); splitting it is tracked under open-items L2",
    "function parseArguments(argv) {",
    "  const [command, ...rest] = argv;",
    "  /** @type {TmuxHelperOptions} */",
    "  const options = {",
    "    window: null,",
    "    all: false,",
    "    force: false,",
    "    inPlace: false,",
    "    wait: DEFAULT_WAIT_SECONDS,",
    "    handleDigest: null,",
    "    promptRef: null,",
    "    promptDigest: null,",
    "    waitLanding: DEFAULT_LANDING_WAIT_SECONDS,",
    "    text: null,",
    "  };",
    "  for (let index = 0; index < rest.length; index += 1) {",
    "    const argument = rest[index];",
    "    if (argument === \"--all\") {",
    "      options.all = true;",
    "    } else if (argument === \"--force\") {",
    "      options.force = true;",
    "    } else if (argument === \"--in-place\") {",
    "      options.inPlace = true;",
    "    } else if (argument === \"--window\") {",
    "      options.window = parseWindowId(rest[index + 1], \"--window\");",
    "      index += 1;",
    "    } else if (argument === \"--wait\") {",
    "      const seconds = Number(rest[index + 1]);",
    "      if (!Number.isInteger(seconds) || seconds < 0 || seconds > MAX_WAIT_SECONDS)",
    "        refuse(\"wait-invalid\");",
    "      options.wait = seconds;",
    "      index += 1;",
    "    } else if (argument === \"--wait-landing\") {",
    "      const seconds = Number(rest[index + 1]);",
    "      if (!Number.isInteger(seconds) || seconds < 0 || seconds > MAX_WAIT_SECONDS)",
    "        refuse(\"wait-landing-invalid\");",
    "      options.waitLanding = seconds;",
    "      index += 1;",
    "    } else if (argument === \"--text\") {",
    "      const text = rest[index + 1];",
    "      const characters = typeof text === \"string\" ? [...text] : [];",
    "      if (",
    "        characters.length === 0 ||",
    "        characters.length > NUDGE_TEXT_MAXIMUM ||",
    "        text.trim().length === 0 ||",
    "        characters.some((character) => isControl(character.codePointAt(0) ?? 0))",
    "      ) {",
    "        refuse(\"text-invalid\");",
    "      }",
    "      options.text = text;",
    "      index += 1;",
    "    } else if (argument === \"--handle-digest\") {",
    "      const digest = rest[index + 1];",
    "      if (typeof digest !== \"string\" || !DIGEST_PATTERN.test(digest))",
    "        refuse(\"handle-digest-invalid\");",
    "      options.handleDigest = digest;",
    "      index += 1;",
    "    } else if (argument === \"--prompt-ref\") {",
    "      const ref = rest[index + 1];",
    "      if (!isPermitPromptRef(ref)) refuse(\"prompt-ref-invalid\");",
    "      options.promptRef = ref;",
    "      index += 1;",
    "    } else if (argument === \"--prompt-digest\") {",
    "      const digest = rest[index + 1];",
    "      if (typeof digest !== \"string\" || !DIGEST_PATTERN.test(digest))",
    "        refuse(\"prompt-digest-invalid\");",
    "      options.promptDigest = digest;",
    "      index += 1;",
    "    } else {",
    "      refuse(\"argument-unknown\");",
    "    }",
    "  }",
    "  return Object.freeze({ command: command ?? null, options: Object.freeze(options) });",
    "}",
    "",
    "/**",
    " * @param {HelperConfig} config",
    " * @returns {string}",
    " */",
    "function primaryControllerWindowId(config) {",
    "  const primary = config.pods.find((pod) => pod?.placement === \"primary\");",
    "  const controller = config.topology.windows.find(",
    "    (window) =>",
    "      window?.role === \"controller\" && (primary === undefined || window?.podId === primary.podId),",
    "  );",
    "  if (controller === undefined || typeof controller.windowId !== \"string\")",
    "    refuse(\"controller-window-unknown\");",
    "  return controller.windowId;",
    "}",
    "",
    "/**",
    " * @param {JsonRecord} input",
